<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_clothing_warehouse_access();$page_title='Barcode Scan';require __DIR__.'/../includes/header.php';$barcode=trim($_GET['barcode']??'');$product=null;if($barcode!==''){$s=$pdo->prepare('SELECT p.*,l.location_code FROM products p LEFT JOIN warehouse_locations l ON l.id=p.location_id WHERE p.barcode=? OR p.product_code=?');$s->execute([$barcode,$barcode]);$product=$s->fetch(PDO::FETCH_ASSOC);}?>
<div class="mb-4"><h1 class="page-heading"><?=e(t('barcode_scan'))?></h1><p class="page-subtitle mb-0"><?=current_language()==='zh'?'使用条码扫描器输入条码，或手动输入货品条码。':'Use a barcode scanner or enter a product barcode manually.'?></p></div><div class="panel"><form class="row g-2"><div class="col-md-8"><input class="form-control" autofocus name="barcode" value="<?=e($barcode)?>" placeholder="<?=e(t('barcode_placeholder'))?>"></div><div class="col-md-2"><button class="btn btn-primary w-100"><?=e(t('barcode_scan'))?></button></div></form><?php if($barcode!==''&&!$product):?><div class="alert alert-warning mt-4">Product not found.</div><?php elseif($product):?><div class="row mt-4"><div class="col-md-6"><h2 class="h5"><?=e($product['product_name'])?></h2><p class="text-muted mb-1"><?=e(t('product_code'))?>: <?=e($product['product_code'])?></p><p class="text-muted"><?=e(t('barcode'))?>: <?=e($product['barcode'])?></p></div><div class="col-md-3"><div class="metric-number"><?=number_format($product['current_quantity'],2)?></div><div class="metric-label"><?=e(t('available_stock'))?> (<?=e($product['unit'])?>)</div></div><div class="col-md-3"><b><?=e(t('storage_location'))?></b><p><?=e($product['location_code']??'—')?></p></div></div><?php endif?></div><?php require __DIR__.'/../includes/footer.php'; ?>
